function translate(){const dict={...fallback,...langs[activeLang]};document.documentElement.lang=activeLang;document.querySelectorAll('[data-i18n]').forEach(el=>{const text=dict[el.dataset.i18n];if(text)el.textContent=text});document.querySelector('#language').value=activeLang;document.title=document.title.replace(/^.*? \| /,'')+' | JasaTiketMurah';}
