let answer;function captcha(){const a=Math.floor(Math.random()*90)+10,b=Math.floor(Math.random()*(a+1));answer=a-b;const label=document.querySelector('#captcha-label');if(label)label.firstChild.textContent=`${(langs[activeLang]||fallback).verification||fallback.verification}: ${a} − ${b} = `}captcha();document.querySelector('#contact-form')?.addEventListener('submit',e=>{e.preventDefault();const f=document.querySelector('#contact-feedback');if(Number(document.querySelector('#captcha').value)!==answer){f.textContent='Jawaban verifikasi belum tepat.';captcha();return}f.textContent='Terima kasih. Pesan Anda siap dikirim ke tim kami.';e.currentTarget.reset();captcha()});

