  const departure=document.querySelector('#travel-date');const returnField=document.createElement('label');returnField.className='return-date';returnField.hidden=true;returnField.innerHTML='<small>Tanggal pulang</small><input id="return-date" type="date">';departure.parentElement.after(returnField);const returnDate=returnField.querySelector('input');
