// Search state is deliberately session-only: it disappears when the tab/window closes.
// Live supplier data is fetched only after the server-side API gateway is connected.
document.head.insertAdjacentHTML('beforeend','<style>.booking-hero{background:linear-gradient(90deg,rgba(13,27,42,.94) 0%,rgba(13,27,42,.78) 46%,rgba(13,27,42,.30) 100%),url("/assets/hero-booking.png") center/cover no-repeat}.booking-hero h1{color:#fff;max-width:680px}.booking-hero .hero-sub{color:#eaf5fb;max-width:600px}.search-card{box-shadow:0 18px 42px rgba(13,27,42,.22)}@media(max-width:700px){.booking-hero{background-position:60% center}}</style>');
const searchForm=document.querySelector('#search-form');let idleSearchTimer;
const clearSearchSession=()=>{sessionStorage.removeItem('jtm-last-search');sessionStorage.removeItem('jtm-search-results');const notice=document.querySelector('#search-feedback');if(notice&&notice.dataset.searchState==='stored'){notice.textContent='Sesi pencarian berakhir. Cari lagi untuk mendapatkan data terbaru dari API.';notice.dataset.searchState='expired'}};
const resetSearchIdleTimer=()=>{clearTimeout(idleSearchTimer);idleSearchTimer=setTimeout(clearSearchSession,30000)};
if(searchForm){searchForm.querySelectorAll('input,select,button').forEach(control=>['input','change','focus','click'].forEach(eventName=>control.addEventListener(eventName,resetSearchIdleTimer)));searchForm.addEventListener('submit',()=>{sessionStorage.setItem('jtm-last-search',JSON.stringify({origin:document.querySelector('#origin')?.value||'',destination:document.querySelector('#destination')?.value||'',travelDate:document.querySelector('#travel-date')?.value||'',savedAt:Date.now()}));const notice=document.querySelector('#search-feedback');if(notice)notice.dataset.searchState='stored';resetSearchIdleTimer()});resetSearchIdleTimer()}
window.addEventListener('pagehide',clearSearchSession);

// Local airport catalogue for the first search experience. The production gateway
// will replace this with its supplier-backed airport index.
const airportCatalogue=[
  {code:'CGK',city:'Jakarta',name:'Soekarno-Hatta International Airport'},
  {code:'HLP',city:'Jakarta',name:'Halim Perdanakusuma International Airport'},
  {code:'DPS',city:'Denpasar',name:'I Gusti Ngurah Rai International Airport'},
  {code:'SUB',city:'Surabaya',name:'Juanda International Airport'},
  {code:'KNO',city:'Medan',name:'Kualanamu International Airport'},
  {code:'YIA',city:'Yogyakarta',name:'Yogyakarta International Airport'},
  {code:'SIN',city:'Singapore',name:'Singapore Changi Airport'},
  {code:'KUL',city:'Kuala Lumpur',name:'Kuala Lumpur International Airport'},
  {code:'BKK',city:'Bangkok',name:'Suvarnabhumi Airport'},
  {code:'NRT',city:'Tokyo',name:'Narita International Airport'},
  {code:'ICN',city:'Seoul',name:'Incheon International Airport'},
  {code:'SYD',city:'Sydney',name:'Sydney Kingsford Smith Airport'}
];
const airportValue=airport=>`${airport.city} (${airport.code})`;
const airportMatch=value=>airportCatalogue.find(airport=>airportValue(airport).toLowerCase()===value.trim().toLowerCase());
if(searchForm){
  [document.querySelector('#origin'),document.querySelector('#destination')].forEach(input=>{
    if(!input)return;input.setAttribute('autocomplete','off');const list=document.createElement('div');list.className='airport-suggestions';list.hidden=true;input.parentElement.appendChild(list);
    const render=()=>{const term=input.value.trim().toLowerCase();const matches=airportCatalogue.filter(airport=>`${airport.code} ${airport.city} ${airport.name}`.toLowerCase().includes(term)).slice(0,6);list.innerHTML=matches.map(airport=>`<button type="button" data-airport="${airport.code}"><b>${airport.city} (${airport.code})</b><small>${airport.name}</small></button>`).join('');list.hidden=!matches.length};
    input.addEventListener('input',render);input.addEventListener('focus',render);input.addEventListener('blur',()=>setTimeout(()=>list.hidden=true,140));list.addEventListener('click',event=>{const button=event.target.closest('[data-airport]');if(!button)return;const airport=airportCatalogue.find(item=>item.code===button.dataset.airport);input.value=airportValue(airport);list.hidden=true;input.dispatchEvent(new Event('change',{bubbles:true}))});
  });
  searchForm.addEventListener('submit',event=>{const origin=airportMatch(document.querySelector('#origin')?.value||'');const destination=airportMatch(document.querySelector('#destination')?.value||'');const feedback=document.querySelector('#search-feedback');if(!origin||!destination){event.preventDefault();feedback.textContent='Pilih bandara dari daftar saran agar rute dapat divalidasi.';return}if(origin.code===destination.code){event.preventDefault();feedback.textContent='Bandara keberangkatan dan tujuan harus berbeda.';return}event.preventDefault();const query=new URLSearchParams({from:origin.code,to:destination.code,date:document.querySelector('#travel-date')?.value||''});window.location.href=`/results/?${query.toString()}`});
}
const resultRoot=document.querySelector('#flight-results');
if(resultRoot){
  const query=new URLSearchParams(location.search);const from=query.get('from')||'CGK',to=query.get('to')||'DPS';const samples=[{airline:'Garuda Indonesia',code:'GA',time:'07:10 – 10:05',duration:'1j 55m',stops:0,price:1425000},{airline:'Batik Air',code:'ID',time:'09:20 – 12:15',duration:'1j 55m',stops:0,price:1189000},{airline:'Singapore Airlines',code:'SQ',time:'12:15 – 20:10',duration:'6j 55m',stops:1,price:2099000}];
  const renderResults=()=>{const direct=document.querySelector('#filter-direct')?.checked;const ordered=[...samples].filter(item=>!direct||item.stops===0).sort((a,b)=>document.querySelector('#sort-results')?.value==='price-desc'?b.price-a.price:a.price-b.price);resultRoot.innerHTML=ordered.map(item=>`<article class="flight-result"><div><b>${item.airline}</b><small>${item.code} · Economy</small></div><div><b>${item.time}</b><small>${from} → ${to} · ${item.duration}</small></div><div><small>${item.stops===0?'Langsung':'1 transit'}</small></div><div class="result-price"><b>Rp${item.price.toLocaleString('id-ID')}</b><button type="button">Pilih</button></div></article>`).join('')||'<p>Tidak ada penerbangan yang cocok dengan filter Anda.</p>'};
  document.querySelector('#result-route').textContent=`${from} ke ${to}`;document.querySelectorAll('#filter-direct,#sort-results').forEach(control=>control.addEventListener('change',renderResults));renderResults();
}

document.head.insertAdjacentHTML('beforeend','<style>.booking-hero{background:linear-gradient(180deg,rgba(13,27,42,.72) 0%,rgba(13,27,42,.10) 28%,rgba(13,27,42,.10) 68%,rgba(13,27,42,.70) 100%),linear-gradient(90deg,rgba(13,27,42,.86),rgba(13,27,42,.28)),url("/assets/hero-booking.png") center/cover no-repeat}.booking-hero .search-form{grid-template-columns:1.15fr 38px 1.15fr 1fr .9fr .9fr}.booking-hero .search-form .primary-button{grid-column:1/-1;justify-self:end;min-width:170px;margin-top:8px}.booking-extras{display:flex;gap:12px;align-items:center;margin-top:14px}.group-booking-link{color:#fff;background:rgba(255,255,255,.15);border:1px solid rgba(255,255,255,.55);border-radius:5px;padding:10px 14px;font-size:.86rem;font-weight:700;text-decoration:none}.charter-tab{color:#0d1b2a!important}@media(max-width:1000px){.booking-hero .search-form{grid-template-columns:1fr 36px 1fr 1fr}.booking-hero .search-form .primary-button{grid-column:1/-1}}@media(max-width:700px){.booking-extras{align-items:stretch}.group-booking-link{text-align:center}.booking-hero .search-form{grid-template-columns:1fr}.booking-hero .search-form .primary-button{justify-self:stretch}.site-header{padding-inline:16px}.brand img{width:158px}.booking-hero h1{font-size:clamp(2rem,10vw,3rem)}.service-tab{font-size:.82rem}}@media(max-width:390px){.brand img{width:138px}.wrap{width:calc(100% - 24px)}.search-card{padding-inline:12px}}</style>');
document.querySelector('.brand')?.setAttribute('href','/');document.querySelector('[data-service="hotel"]')?.firstChild.replaceWith('🛏️ ');document.querySelectorAll('.service-tile').forEach(tile=>{if(tile.querySelector('[data-i18n="hotel"]'))tile.firstChild.replaceWith('🛏️')});
const polishLanguage=document.querySelector('#language');if(polishLanguage){polishLanguage.innerHTML='<option value="id">🇮🇩 Bahasa Indonesia</option><option value="en">🇬🇧 English</option><option value="km">🇰🇭 ខ្មែរ</option><option value="zh-Hans">🇨🇳 简体中文</option><option value="zh-Hant">🇹🇼 繁體中文</option><option value="ja">🇯🇵 日本語</option><option value="ko">🇰🇷 한국어</option><option value="ms">🇲🇾 Bahasa Melayu</option><option value="my">🇲🇲 မြန်မာ</option><option value="pt">🇵🇹 Português</option><option value="fil">🇵🇭 Tagalog</option><option value="th">🇹🇭 ไทย</option><option value="tr">🇹🇷 Türkçe</option><option value="vi">🇻🇳 Tiếng Việt</option>';polishLanguage.value=activeLang}document.querySelector('#currency')?.replaceChildren(...['IDR','AUD','CAD','CNY','GBP','JPY','KRW','MYR','NZD','PHP','SGD','USD','VND'].map(code=>new Option(code,code)));
if(bookingForm){const serviceTabs=document.querySelector('.service-tabs');if(serviceTabs&&!serviceTabs.querySelector('[data-service="charter"]'))serviceTabs.insertAdjacentHTML('beforeend','<a class="service-tab charter-tab" data-service="charter" href="/charter/">🛩️ <b>Private Jet Charter</b></a>');const searchButton=bookingForm.querySelector('.primary-button');if(searchButton&&!bookingForm.querySelector('#booking-class'))searchButton.insertAdjacentHTML('beforebegin','<label><small data-runtime="bookingClass">Kelas pemesanan</small><select id="booking-class" name="booking-class"><option>Ekonomi</option><option>Ekonomi Premium</option><option>Bisnis</option><option>Kelas Utama / Suites</option></select></label>');if(!document.querySelector('.group-booking-link'))bookingForm.insertAdjacentHTML('afterend','<div class="booking-extras"><a class="group-booking-link" href="/group-booking/">Ingin melakukan group booking lebih dari 10 orang? Bisa. Yuk klik di sini</a></div>')}
const groupForm=document.querySelector('#group-booking-form');if(groupForm){let groupAnswer;const groupCaptcha=()=>{const first=Math.floor(Math.random()*90)+10,second=Math.floor(Math.random()*(first+1));groupAnswer=first-second;document.querySelector('#group-captcha-label').textContent=`Verifikasi: ${first} − ${second} = `};groupCaptcha();groupForm.addEventListener('submit',async event=>{event.preventDefault();const feedback=document.querySelector('#group-booking-feedback');if(Number(document.querySelector('#group-captcha').value)!==groupAnswer){feedback.textContent='Jawaban verifikasi belum tepat.';groupCaptcha();return}const payload=Object.fromEntries(new FormData(groupForm));feedback.textContent='Mengirim permintaan Anda…';try{const response=await fetch('/api/group-booking.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok)throw new Error();feedback.textContent='Permintaan terkirim. Salinan email telah dikirim ke alamat Anda.';groupForm.reset()}catch{sessionStorage.setItem('jtm-group-booking',JSON.stringify(payload));feedback.textContent='Permintaan tersimpan. Layanan email sedang tidak tersedia; tim kami akan menindaklanjuti.'}groupCaptcha()})}

// Checkout is intentionally client-side until payment and account services are connected.
const generateOrderNumber=(type='F')=>`JTM${type}${Math.floor(Date.now()/1000)}`;
document.querySelector('#flight-results')?.addEventListener('click',event=>{const button=event.target.closest('.result-price button');if(!button)return;const card=button.closest('.flight-result');const price=card.querySelector('.result-price b')?.textContent||'';const airline=card.querySelector('b')?.textContent||'';window.location.href=`/checkout/?airline=${encodeURIComponent(airline)}&price=${encodeURIComponent(price)}&route=${encodeURIComponent(document.querySelector('#result-route')?.textContent||'')}`});
const checkoutForm=document.querySelector('#checkout-form');if(checkoutForm){const query=new URLSearchParams(location.search);document.querySelector('#checkout-route').textContent=query.get('route')||'CGK → DPS';document.querySelector('#checkout-airline').textContent=query.get('airline')||'Batik Air';document.querySelector('#checkout-total').textContent=query.get('price')||'Rp1.189.000';document.querySelector('#checkout-date').textContent=new Intl.DateTimeFormat('id-ID',{dateStyle:'medium'}).format(new Date());checkoutForm.querySelectorAll('[name="bookingMode"]').forEach(input=>input.addEventListener('change',()=>{const member=input.value==='member'&&input.checked;const password=checkoutForm.querySelector('.member-password');password.hidden=!member;password.querySelector('input').required=member}));checkoutForm.addEventListener('submit',event=>{event.preventDefault();const orderNumber=generateOrderNumber('F');sessionStorage.setItem('jtm-order',JSON.stringify({number:orderNumber,customer:Object.fromEntries(new FormData(checkoutForm)),route:query.get('route'),price:query.get('price')}));window.location.href=`/order-confirmation/?order=${orderNumber}`})}
const confirmation=document.querySelector('#order-number');if(confirmation){const order=new URLSearchParams(location.search).get('order')||JSON.parse(sessionStorage.getItem('jtm-order')||'{}').number||generateOrderNumber('F');confirmation.textContent=order;const detail=JSON.parse(sessionStorage.getItem('jtm-order')||'{}');if(detail.customer?.email)document.querySelector('#order-confirmation-detail').textContent=`Ringkasan pesanan dikirim ke ${detail.customer.email}.`}

const runtimeCopy=()=>window.JTM_I18N?.runtime?.[activeLang]||window.JTM_I18N?.runtime?.en||{departure:'Departure date',return:'Return date',passengers:'Passengers',bookingClass:'Booking class',oneWay:'One way',roundTrip:'Round trip',multiCity:'Multi-city',direct:'Direct flights only',adult:'adult',child:'child',infant:'infant'};
const refreshDynamicLocale=()=>{const copy=runtimeCopy();document.querySelector('#travel-date')?.previousElementSibling&&(document.querySelector('#travel-date').previousElementSibling.textContent=copy.departure);document.querySelector('#return-date')?.parentElement.querySelector('small')&&(document.querySelector('#return-date').parentElement.querySelector('small').textContent=copy.return);document.querySelector('.traveller-trigger')?.previousElementSibling&&(document.querySelector('.traveller-trigger').previousElementSibling.textContent=copy.passengers);document.querySelectorAll('.trip-types label:not(.direct-choice)').forEach((label,index)=>label.lastChild.textContent=[' '+copy.oneWay,' '+copy.roundTrip,' '+copy.multiCity][index]);document.querySelector('[data-runtime="direct"]')&&(document.querySelector('[data-runtime="direct"]').textContent=copy.direct);document.querySelector('[data-runtime="bookingClass"]')&&(document.querySelector('[data-runtime="bookingClass"]').textContent=copy.bookingClass)};refreshDynamicLocale();document.querySelector('#language')?.addEventListener('change',()=>setTimeout(refreshDynamicLocale));document.addEventListener('jtm-i18n-ready',refreshDynamicLocale);
const refreshPassengerCopy=()=>{const copy=runtimeCopy();const values=['adults','children','infants'].map(key=>Number(document.querySelector(`[data-count="${key}"]`)?.textContent||0));const trigger=document.querySelector('.traveller-trigger');if(trigger)trigger.textContent=[values[0]&&`${values[0]} ${copy.adult}`,values[1]&&`${values[1]} ${copy.child}`,values[2]&&`${values[2]} ${copy.infant}`].filter(Boolean).join(', ');document.querySelectorAll('.traveller-row b').forEach((item,index)=>item.textContent=[copy.adult,copy.child,copy.infant][index])};refreshPassengerCopy();document.querySelector('#language')?.addEventListener('change',()=>setTimeout(refreshPassengerCopy));document.addEventListener('jtm-i18n-ready',refreshPassengerCopy);
setTimeout(()=>{const form=document.querySelector('#multi-city-form');if(!form)return;const airports=['Jakarta (CGK)','Denpasar (DPS)','Surabaya (SUB)','Yogyakarta (YIA)','Medan (KNO)','Singapore (SIN)','Kuala Lumpur (KUL)','Bangkok (BKK)','Tokyo (NRT)','Seoul (ICN)'];const list=document.createElement('datalist');list.id='multi-city-airports';list.innerHTML=airports.map(airport=>`<option value="${airport}">`).join('');document.body.appendChild(list);const decorate=()=>form.querySelectorAll('.route-row input:not([type="date"])').forEach(input=>{input.setAttribute('list','multi-city-airports');input.setAttribute('autocomplete','off')});decorate();new MutationObserver(decorate).observe(form,{childList:true,subtree:true})},0);
